/// <summary>
/// Get table record of METItemSiteSettingsSetup
/// </summary>
/// <param name="_pricingObject">
/// The <c>Common</c> object that will be used to get the table record
/// </param>
/// <returns><c>METItemSiteSettingsSetup</c> object</returns>
protected METItemSiteSettingsSetup getTableRecord(Common _pricingObject)
{
    SalesLine		salesLine		    = _pricingObject as SalesLine;
    InventDim       salesLineInventDim  = InventDim::find(salesLine.InventDimId);
    
    METItemSiteSettingsSetup	metItemSiteSettingsSetup	= METItemSiteSettingsSetup::find(salesLine.ItemId, salesLineInventDim.InventSiteId);
 
    return metItemSiteSettingsSetup;
}

/// <summary>
/// Get value datasource identifier table string
/// </summary>
/// <returns>table name string</returns>
public str getQueryBuilderDatasourceIdentifier()
{
    return tableStr(METItemSiteSettingsSetup);
}

    /// <summary>
    /// Get value query build datasource object
    /// </summary>
    /// /// <param name="_query">
    /// The <c>Query</c> object that will be used to generate query datasource
    /// </param>
    /// /// <param name="_qbdsMap">
    /// The <c>Map</c> object that will be used to manage METItemSiteSettingsSetup records
    /// </param>
    /// <returns><c>QueryBuildDataSource</c> object</returns>
    protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
    {
        QueryBuildDataSource qbds, qbdsRoot;

        if (_qbdsMap && _qbdsMap.exists(tableStr(InventTable)))
        {
            qbdsRoot = _qbdsMap.lookup(tableStr(InventTable));
        }
        else
        {
            qbdsRoot = _query.addDataSource(tableNum(InventTable));

            if (_qbdsMap)
            {
                _qbdsMap.insert(tableStr(InventTable), qbdsRoot);
            }
        }

        if (_qbdsMap && _qbdsMap.exists(this.getQueryBuilderDatasourceIdentifier()))
        {
            qbds = _qbdsMap.lookup(this.getQueryBuilderDatasourceIdentifier());
        }
        else
        {
            qbds = qbdsRoot.addDataSource(tableNum(METItemSiteSettingsSetup));
            qbds.addLink(fieldNum(InventTable, ItemId), fieldNum(METItemSiteSettingsSetup, ItemId));
            qbds.joinMode(JoinMode::ExistsJoin);
            
            if (_qbdsMap)
            {
                _qbdsMap.insert(this.getQueryBuilderDatasourceIdentifier(), qbds);
            }
        }
        return qbds;
    }

    /// <summary>
    /// Builds pricing object query
    /// </summary>
    /// <param name="_query">
    /// The <c>Query</c> object that the new ranges will be added to.
    /// </param>
    /// <param name="_value">
    /// The <c>anytype</c> object that determines the METItemSiteSettingsSetup record.
    /// </param>
    /// <param name="_qdbsMap">
    /// The <c>Map</c> object that is used to identify the query build data source.
    /// </param>
    /// <returns><c>Query</c> object</returns>
    public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
    {
        QueryBuildDataSource qbds;

        qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
        this.setQueryBuildDatasourceRange(qbds, _value);

        return _query;
    }

					
    /// <summary>
    /// Get the table name
    /// </summary>
    /// <returns>
    /// Returns a TableName object
    /// </returns>
    public TableName getTableName()
    {
        return tableStr(METItemSiteSettingsSetup);
    }
